<?php
namespace App\Filament\Resources;
use App\Filament\Resources\CuratorPlanResource\Pages;use App\Models\CuratorPlan;use Illuminate\Support\Facades\DB;
use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\Resource;use Filament\Resources\Table;use Filament\Tables;
class CuratorPlanResource extends Resource{protected static ?string $model=CuratorPlan::class;protected static ?string $modelLabel='план';protected static ?string $pluralModelLabel='Планы кураторов';public static function form(Form $form):Form{return $form->schema([Forms\Components\Select::make('study_group_id')->label('Группа')->options(fn()=>DB::table('study_groups')->where('active',1)->orderBy('name')->pluck('name','id'))->searchable()->required(),Forms\Components\TextInput::make('title')->label('Название')->required(),Forms\Components\Textarea::make('goals')->label('Цели')->columnSpan('full')])->columns(2);}public static function table(Table $table):Table{return $table->columns([Tables\Columns\TextColumn::make('study_group_id')->label('Группа')->formatStateUsing(fn($state)=>DB::table('study_groups')->where('id',$state)->value('name') ?: '—'),Tables\Columns\TextColumn::make('title')->label('План')->searchable(),Tables\Columns\TextColumn::make('goals')->label('Цели')->limit(80),Tables\Columns\BadgeColumn::make('status')->label('Статус')])->actions([Tables\Actions\EditAction::make()->label('Изменить'),Tables\Actions\Action::make('archive')->label('В архив')->color('danger')->requiresConfirmation()->action(fn($record)=>$record->update(['archived_at'=>now()]))]);}public static function getEloquentQuery():\Illuminate\Database\Eloquent\Builder{return parent::getEloquentQuery()->whereNull('archived_at');}public static function getPages():array{return['index'=>Pages\ListCuratorPlans::route('/'),'create'=>Pages\CreateCuratorPlan::route('/create'),'edit'=>Pages\EditCuratorPlan::route('/{record}/edit')];}}
